import { useEffect, useState } from "react";
import type { ReactNode } from "react";
import { AccessibilityInfo, Animated, Easing, StyleSheet, View } from "react-native";
import type { StyleProp, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface SkeletonProps extends Omit<ViewProps, "children"> {
  /** Accessible name announced while loading. */
  label?: string;
  lines?: number;
  avatar?: boolean;
  /** Shown instead of the placeholder once `loading` is false. */
  children?: ReactNode;
  loading?: boolean;
  /** Extend the inner, named parts of the skeleton: avatar, lines or line. The React Native counterpart of `classNames`. */
  styles?: {
    avatar?: StyleProp<ViewStyle>;
    lines?: StyleProp<ViewStyle>;
    line?: StyleProp<ViewStyle>;
  };
}

export function Skeleton({ label = "Loading", lines = 3, avatar = false, children, loading = true, style, styles: parts, ...props }: SkeletonProps) {
  const tokens = useTokens();
  const [pulse] = useState(() => new Animated.Value(1));
  const [reduceMotion, setReduceMotion] = useState(false);

  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
  }, []);

  // A calm, finite pulse that rests after about 20 seconds, like the web version.
  useEffect(() => {
    if (!loading || reduceMotion) return;
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(pulse, { toValue: 0.52, duration: 900, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
        Animated.timing(pulse, { toValue: 1, duration: 900, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
      ]),
      { iterations: 11 },
    );
    loop.start();
    return () => loop.stop();
  }, [loading, reduceMotion, pulse]);

  if (!loading && children !== undefined) return <>{children}</>;

  const fill = `${tokens.borderStrong}61`;
  const bar = { backgroundColor: fill, opacity: pulse, borderRadius: metrics.radiusControl };

  return (
    <View {...props} accessible accessibilityLabel={label} accessibilityState={{ busy: true }} style={[local.root, style]}>
      {avatar ? <Animated.View style={[bar, local.avatar, parts?.avatar]} /> : null}
      <View style={[local.lines, parts?.lines]}>
        {Array.from({ length: lines }, (_, index) => (
          <Animated.View
            key={index}
            style={[
              bar,
              local.line,
              // First line is a heading, last is short, like text that ends mid-line.
              { width: index === 0 ? "48%" : index === lines - 1 ? "72%" : "100%", height: index === 0 ? metrics.space[4] : metrics.space[3] },
              parts?.line,
            ]}
          />
        ))}
      </View>
    </View>
  );
}

const local = StyleSheet.create({
  root: { flexDirection: "row", alignItems: "flex-start", gap: metrics.space[4], alignSelf: "stretch" },
  avatar: { width: metrics.controlHeight.md, height: metrics.controlHeight.md, borderRadius: metrics.radiusPill },
  lines: { flex: 1, gap: metrics.space[3], paddingTop: metrics.space[1] },
  line: {},
});

export default Skeleton;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
